761	fn draw_input_bar(stdout: &mut impl Write, prefix: &str, value: &str, w: usize, h: usize) -> io::Result<()> {
762	    let prefix_len = prefix.chars().count();
763	    let text: String = value.chars().take(w.saturating_sub(prefix_len + 2)).collect();
764	    let content = format!("{prefix}{text}");
765	    let padded = format!("{:<width$}", content, width = w);
766	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
767	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
768	    let col = (prefix_len + text.chars().count()).min(w.saturating_sub(1)) as u16;
769	    execute!(stdout, cursor::MoveTo(col, (h - 1) as u16))?;
770	    stdout.flush()
771	}
