        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
        write!(stdout, "\x1b[1;38;5;203m  Tidy — stale worktrees\x1b[0m").ok();
        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();

