                write!(stdout, "  \x1b[38;5;240m... and {} more\x1b[0m", stale.len() - list_h).ok();
                execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
            }
        }

        // Status bar
        let count = stale.len();
        let hint = format!(
